import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {legacyFrom,convergeOrigin} from '../origins.js?v=5.6.0';import {LISTENINGS,listeningLegacy,listeningObjects,listeningInteraction,listeningEpilogue,validateListening} from '../new-game-plus.js?v=5.6.0';import {carryWayglass} from '../wayglass-model.js';import {resonancePoints} from '../resonance-link.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));function world(){return new World(data);}
function completed(w){w.state.complete=true;w.state.chapter=25;w.state.story.finalChoice=1;return w.state;}
test('completed outcomes deterministically select routes, six rotate before repeating, inputs remain intact',()=>{const w=world();let s=completed(w);const seen=new Set();for(let i=0;i<12;i++){const before=JSON.stringify(s),a=listeningLegacy(s);assert.deepEqual(a,listeningLegacy(s));assert.equal(JSON.stringify(s),before);if(i<6){assert.ok(!seen.has(a.routeId));seen.add(a.routeId);}assert.notEqual(a.routeId,s.encore?.routeId);s={...s,encore:a};}assert.equal(seen.size,6);assert.equal(listeningLegacy({complete:false}),null);});
test('origin selection keeps completed account, resets gear and preserves listening through present convergence',()=>{const w=world(),l=legacyFrom(completed(w));w.newGame({originId:'sable-reed',legacy:l});assert.equal(w.state.encore.cycle,1);assert.equal(w.state.encore.history[0].ending,1);assert.equal(w.state.xp,0);w.state.chronicle.step=4;w.state.chronicle.choices={repair:0,destiny:0,approach:'diversion'};convergeOrigin(w);assert.equal(w.state.encore.routeId,l.encore.routeId);const save=w.save();w.restore(save);assert.equal(w.state.encore.history.length,1);});
test('all six routes place three accessible notes, require current Wayglass and validate the actual fibre answer',()=>{const w=world();for(const route of LISTENINGS){w.newGame({quiet:true});w.state.encore={version:1,cycle:1,seed:17,routeId:route.id,solved:[],history:[{ending:1}]};w.state.chapter=24;w.state.story.firstCore=true;assert.equal(listeningObjects(w).length,0);carryWayglass(w.state);for(let index=0;index<3;index++){const scenes=w.data.scenes.filter(s=>s.chapter===route.chapters[index]&&!s.originId&&!s.biome);let note;for(const scene of scenes){w.state.scene=scene.location;note=listeningObjects(w)[0];if(note)break;}assert.ok(note,route.id+':'+index);assert.notEqual(w.scene.floor[note.xy[1]][note.xy[0]],'#');assert.equal(listeningInteraction(w,{...note,xy:[-2,-2]}),true);assert.equal(w.state.encore.solved.length,index);let dialog;w.callbacks.onDialog=d=>dialog=d;w.state.mode='field';listeningInteraction(w,note);const correct=(17+index)%3+1;dialog.choices[correct%3].action();assert.equal(w.state.encore.solved.length,index);w.state.mode='field';listeningInteraction(w,note);dialog.choices[correct-1].action();assert.equal(w.state.encore.solved.length,index+1);w.state.mode='field';listeningInteraction(w,note);assert.equal(w.state.encore.solved.length,index+1);}assert.equal(resonancePoints(w.state),5);assert.ok(w.state.supports.includes(route.support));assert.equal(listeningEpilogue(w.state).length,1);}});

test('listening histories remain saveable after more than 512 completed journeys',()=>{let s={complete:true,chapter:25,story:{finalChoice:2},storyChoices:{},project:0};for(let n=1;n<=520;n++){s.encore=listeningLegacy(s);assert.equal(s.encore.cycle,n);assert.ok(s.encore.history.length<=512);assert.doesNotThrow(()=>validateListening(s));}assert.equal(s.encore.history[0].cycle,9);assert.equal(s.encore.history.at(-1).cycle,520);});
test('damaged listening records are rejected before they can crash a future encore',()=>{for(const history of [[null],[{route:'unknown'}],[{ending:9}]])assert.throws(()=>validateListening({encore:{version:1,cycle:1,seed:1,routeId:'river',solved:[],history}}),/Invalid listening/);});
